                   if (dr, dc) != (0, 0)):
                centers.append((r, c))

    # A long 2-rail through the motif determines a perpendicular beam.
    # Fill zero cells on the motif's center row/column, preserving 2/3.
    for r, c in centers:
        vertical_rail = sum(g[rr][c] == 2 for rr in range(h) if abs(rr-r) > 1)
        horizontal_rail = sum(g[r][cc] == 2 for cc in range(w) if abs(cc-c) > 1)
        if vertical_rail > horizontal_rail:
            axis = [(r, cc) for cc in range(w)]
        elif horizontal_rail > vertical_rail:
            axis = [(rr, c) for rr in range(h)]
        else:
            # The ray runs perpendicular to short flanking 2-markers.
            axis = [(r, cc) for cc in range(w)]
        # Color the beam's zero cells. Where it crosses another 2 marker,
        # expand the impact to a 3x3 neighborhood, leaving all marks intact.
        crossings = [(rr, cc) for rr, cc in axis if g[rr][cc] == 2]
        for rr, cc in axis:
            if g[rr][cc] == 0:
                g[rr][cc] = 1
        for rr, cc in crossings:
            for sr in range(rr - 1, rr + 2):
                for sc in range(cc - 1, cc + 2):
                    if not (0 <= sr < h and 0 <= sc < w):
                        continue
                    if (sr, sc) == (rr, cc):
                        continue
                    if g[sr][sc] == 2:
                        # The perpendicular beam also passes through this rail marker.
                        g[sr][sc] = 1
                        for tr in range(sr - 1, sr + 2):
